// Minimal Tiled (.tmj) map types and helpers. The maps are generated by code, but the JSON is valid Tiled
// format, so it can be exported and opened in the Tiled editor.

export interface TiledProperty {
  name: string;
  type: 'string' | 'int' | 'float' | 'bool';
  value: string | number | boolean;
}

export interface TiledObject {
  id: number;
  name: string;
  type: string;
  x: number;
  y: number;
  width: number;
  height: number;
  rotation: 0;
  visible: true;
  point?: boolean;
  properties?: TiledProperty[];
}

export interface TiledTileLayer {
  id: number;
  name: string;
  type: 'tilelayer';
  width: number;
  height: number;
  x: 0;
  y: 0;
  opacity: number;
  visible: boolean;
  data: number[];
}

export interface TiledObjectLayer {
  id: number;
  name: string;
  type: 'objectgroup';
  draworder: 'topdown';
  x: 0;
  y: 0;
  opacity: 1;
  visible: boolean;
  objects: TiledObject[];
}

export type TiledLayer = TiledTileLayer | TiledObjectLayer;

export interface TiledTileset {
  firstgid: number;
  name: string;
  image: string;
  imagewidth: number;
  imageheight: number;
  tilewidth: 16;
  tileheight: 16;
  columns: number;
  tilecount: number;
  margin: 0;
  spacing: 0;
}

export interface TiledMap {
  compressionlevel: -1;
  width: number;
  height: number;
  tilewidth: 16;
  tileheight: 16;
  infinite: false;
  orientation: 'orthogonal';
  renderorder: 'right-down';
  tiledversion: string;
  version: string;
  type: 'map';
  nextlayerid: number;
  nextobjectid: number;
  layers: TiledLayer[];
  tilesets: TiledTileset[];
}

export const prop = (name: string, value: string | number | boolean): TiledProperty => ({
  name,
  type: typeof value === 'number' ? (Number.isInteger(value) ? 'int' : 'float') : typeof value === 'boolean' ? 'bool' : 'string',
  value,
});

export function propsOf(o: TiledObject): Record<string, string | number | boolean> {
  return Object.fromEntries((o.properties ?? []).map((p) => [p.name, p.value]));
}

export class MapBuilder {
  readonly width: number;
  readonly height: number;
  private nextLayer = 1;
  private nextObject = 1;
  layers: TiledLayer[] = [];

  constructor(width: number, height: number) {
    this.width = width;
    this.height = height;
  }

  tileLayer(name: string, visible = true): number[] {
    const data = new Array<number>(this.width * this.height).fill(0);
    this.layers.push({ id: this.nextLayer++, name, type: 'tilelayer', width: this.width, height: this.height, x: 0, y: 0, opacity: 1, visible, data });
    return data;
  }

  objectLayer(name: string): TiledObject[] {
    const objects: TiledObject[] = [];
    this.layers.push({ id: this.nextLayer++, name, type: 'objectgroup', draworder: 'topdown', x: 0, y: 0, opacity: 1, visible: true, objects });
    return objects;
  }

  // A point object: x/y is the bottom-center pixel of a sprite (or a spot), everything else is in properties.
  point(list: TiledObject[], name: string, type: string, x: number, y: number, properties: TiledProperty[] = []): TiledObject {
    const o: TiledObject = { id: this.nextObject++, name, type, x, y, width: 0, height: 0, rotation: 0, visible: true, point: true, properties };
    list.push(o);
    return o;
  }

  rect(list: TiledObject[], name: string, type: string, x: number, y: number, w: number, h: number, properties: TiledProperty[] = []): TiledObject {
    const o: TiledObject = { id: this.nextObject++, name, type, x, y, width: w, height: h, rotation: 0, visible: true, properties };
    list.push(o);
    return o;
  }

  build(tilesets: TiledTileset[]): TiledMap {
    return {
      compressionlevel: -1, width: this.width, height: this.height, tilewidth: 16, tileheight: 16, infinite: false,
      orientation: 'orthogonal', renderorder: 'right-down', tiledversion: '1.10.2', version: '1.10', type: 'map',
      nextlayerid: this.nextLayer, nextobjectid: this.nextObject, layers: this.layers, tilesets,
    };
  }
}
